CREATE TABLE IF NOT EXISTS custom_game_elements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, version INT UNSIGNED NOT NULL DEFAULT 1, data JSON NOT NULL, updated_by BIGINT NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS custom_peds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, version INT UNSIGNED NOT NULL DEFAULT 1, data JSON NOT NULL, updated_by BIGINT NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS custom_teleports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, version INT UNSIGNED NOT NULL DEFAULT 1, data JSON NOT NULL, updated_by BIGINT NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS custom_prices_config (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, version INT UNSIGNED NOT NULL DEFAULT 1, data JSON NOT NULL, updated_by BIGINT NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS custom_editor_audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, account_id BIGINT NOT NULL, kind VARCHAR(16) NOT NULL, element_id BIGINT NOT NULL, action VARCHAR(16) NOT NULL, before_json JSON NULL, after_json JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS custom_source_overrides (source_key VARCHAR(32) PRIMARY KEY, version INT NOT NULL, data JSON NOT NULL, updated_by BIGINT NOT NULL);
